final class SmithCivicRuntime {
 static void run(GameTestHelper h)throws Exception {
  var level=h.getLevel();var server=level.getServer();var forge=ConstructionService.store(server).projects().stream().filter(v->v.blueprint().toString().equals(Profession.BLACKSMITH.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(forge.owner());var store=CommerceService.store(server);var proof=server.getWorldPath(LevelResource.ROOT).resolve("smith-civic-test.nbt");
  var center=ConstructionService.lodge(server).origin().offset(400,5,160);
  if(Files.exists(proof)){
   for(int x=(center.getX()-10)>>4;x<=(center.getX()+10)>>4;x++)for(int z=(center.getZ()-10)>>4;z<=(center.getZ()+10)>>4;z++)level.getChunk(x,z);
   h.assertTrue(SmithCommunityForge.scan(p,center).startsWith("civicforge="),"Actual retained native shared forge, safe access, stored fuel and active furnace survive restart");var saved=AtomicNbt.read(proof);h.assertTrue(store.professions(p.getUUID()).track(Profession.BLACKSMITH).completedQuestIds().contains(SmithCommunityForge.QUEST)&&store.professions(p.getUUID()).track(Profession.BLACKSMITH).xp()==saved.getLong("xp"),"Original canonical civic inspection and earned XP survive second JVM");h.assertTrue(level.getEntity(forge.npc())!=null&&ConstructionService.structureIntact(level,forge),"Original paid forge/NPC remain intact");com.mojang.logging.LogUtils.getLogger().info("SMITH_CIVIC_RESTART_PASSED: canonical actual civic inspection/300XP/old native Master progress/original paid forge-NPC restored");h.succeed();return;}
  var track=store.professions(p.getUUID()).track(Profession.BLACKSMITH);h.assertTrue(track.completedQuestIds().contains("kingdom_smp:blacksmith/m01")&&track.completedQuestIds().contains("kingdom_smp:blacksmith/m04"),"Actual prior native Nether hardware and volcanic orders precede civic project");long before=track.xp();
  for(int x=(center.getX()-10)>>4;x<=(center.getX()+10)>>4;x++)for(int z=(center.getZ()-10)>>4;z<=(center.getZ()+10)>>4;z++){level.getChunk(x,z);var cell=new BlockPos(x*16,center.getY(),z*16);ClaimRuntimeTests.ftbClaim(p,cell);ClaimRuntimeTests.opacClaim(level,p.getUUID(),cell);}
  for(var cell:BlockPos.betweenClosed(center.offset(-9,-1,-9),center.offset(9,-1,9))){h.assertTrue(level.getBlockState(cell.above()).isAir(),"Private civic fixture does not replace any existing above-ground property");level.setBlock(cell,Blocks.STONE.defaultBlockState(),3);}
  var f1=center.offset(-2,0,2);var f2=center.offset(2,0,2);place(h,p,f1,Items.FURNACE);place(h,p,f2,Items.BLAST_FURNACE);place(h,p,center.offset(2,0,-2),Items.ANVIL);place(h,p,center.offset(-3,0,-3),Items.BARREL);place(h,p,center.offset(3,0,-3),Items.BARREL);place(h,p,center.offset(-2,0,-2),Items.CAULDRON);place(h,p,center.offset(0,0,4),Items.TORCH);
  var old=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));var water=center.offset(-2,0,-2);BlacksmithRepairRuntime.near(p,water);p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(water),Direction.UP,water,false));h.assertTrue(p.getMainHandItem().is(Items.BUCKET)&&level.getBlockState(water).is(Blocks.WATER_CAULDRON),"Native supplied water bucket fills real safety cauldron");p.setItemInHand(InteractionHand.MAIN_HAND,old);
  var hut=BuilderHutSavedData.get(server).hut().orElseThrow();var admin=ClaimRuntimeTests.vanillaPlayer(level,ConstructionService.store(server).reward(ConstructionService.STARTING_HUT).orElseThrow().owner(),ConstructionService.store(server).reward(ConstructionService.STARTING_HUT).orElseThrow().ownerName());server.getPlayerList().op(admin.getGameProfile());admin.moveTo(center.getX()+.5,center.getY(),center.getZ()+.5);p.moveTo(center.getX()+1.5,center.getY(),center.getZ()+.5);
  try {
   boolean denied=false;try{ProfessionInspectionService.review(admin,p,SmithCommunityForge.QUEST,center,"Community native forge and safety inspected");}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Cold furniture cannot qualify as a genuinely running forge");
   for(var pos:java.util.List.of(f1,f2)){var be=(AbstractFurnaceBlockEntity)level.getBlockEntity(pos);be.setItem(0,new ItemStack(Items.RAW_IRON,8));be.setItem(1,new ItemStack(Items.COAL,2));for(int n=0;n<210;n++)AbstractFurnaceBlockEntity.serverTick(level,pos,level.getBlockState(pos),be);h.assertTrue(be.getItem(2).is(Items.IRON_INGOT)&&be.getItem(1).getCount()==1,"Actual native furnace smelts iron and debits supplied coal");}
   var stale=ProfessionInspectionService.review(admin,p,SmithCommunityForge.QUEST,center,"Community native forge and safety inspected");var original=level.getBlockState(water);level.setBlock(water,Blocks.CAULDRON.defaultBlockState(),3);denied=false;try{ProfessionInspectionService.confirm(admin,stale);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(p.getUUID()).track(Profession.BLACKSMITH).xp()==before,"Post-review water loss refuses without XP");level.setBlock(water,original,3);
   var review=ProfessionInspectionService.review(admin,p,SmithCommunityForge.QUEST,center,"Community native forge and safety inspected");var claim=center.offset(8,0,8);ClaimRuntimeTests.opacUnclaim(level,claim);ClaimRuntimeTests.opacClaim(level,admin.getUUID(),claim);denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Current independent OPAC ownership revocation refuses");ClaimRuntimeTests.opacUnclaim(level,claim);ClaimRuntimeTests.opacClaim(level,p.getUUID(),claim);
   review=ProfessionInspectionService.review(admin,p,SmithCommunityForge.QUEST,center,"Community native forge and safety inspected");ClaimRuntimeTests.ftbUnclaim(level,claim);ClaimRuntimeTests.ftbClaim(admin,claim);denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Current independent FTB ownership revocation refuses");ClaimRuntimeTests.ftbUnclaim(level,claim);ClaimRuntimeTests.ftbClaim(p,claim);
   review=ProfessionInspectionService.review(admin,p,SmithCommunityForge.QUEST,center,"Community native forge and safety inspected");ProfessionInspectionService.confirm(admin,review);denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(p.getUUID()).track(Profession.BLACKSMITH).xp()==before+300,"Current confirmed civic project awards exactly300XP once");
  }finally{server.getPlayerList().deop(admin.getGameProfile());}
  var saved=new CompoundTag();saved.putLong("xp",before+300);AtomicNbt.write(proof,saved);CommerceService.checkpoint(p);h.assertTrue(EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data")).professions(p.getUUID()).equals(store.professions(p.getUUID())),"Canonical inspection journal reopens exactly");com.mojang.logging.LogUtils.getLogger().info("SMITH_CIVIC_NATIVE_PASSED: actual retained native civic furnace/anvil/storage/water/light/safe access; paid smelting/material/fuel debit; cold/changed water/currentFTB+OPAC/replay refusals; confirmed canonical300XP; original20native proofs/forge/NPC retained, no quest/source/XP/rank injection");h.succeed();
 }
 static void place(GameTestHelper h,ServerPlayer p,BlockPos at,Item item){var old=p.getMainHandItem().copy();BlacksmithRepairRuntime.near(p,at);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));p.gameMode.useItemOn(p,p.serverLevel(),p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.below()).add(0,.5,0),Direction.UP,at.below(),false));h.assertTrue(p.getMainHandItem().isEmpty()&&!p.serverLevel().getBlockState(at).isAir(),"Real native item placement consumes "+item);p.setItemInHand(InteractionHand.MAIN_HAND,old);}
}
